#!/usr/bin/env bash
# REX2 self-contained source installer: Rust server 0.3.0, Xray v26.3.27 baseline.
# Embedded source package SHA256: 5974cf714c934b4bceae9173efaeddfe4b617390a2e0d422684e9d8b7cd7ae67
set -euo pipefail
umask 077

show_xray_info() {
    command -v python3 >/dev/null || { echo '需要 python3。请先安装 python3，或先执行本脚本的安装模式。' >&2; return 1; }
    python3 - "$@" <<'PY_XRAY_FIELDS'
"""Print only REALITY targets and serverNames, using Xray's own config parser."""
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys

LOCATION_KEYS = (
    "xray.location.config", "XRAY_LOCATION_CONFIG",
    "xray.location.confdir", "XRAY_LOCATION_CONFDIR",
)


def config_flags(argv):
    result = []
    iterator = iter(argv[1:])
    for arg in iterator:
        flag, equal, value = arg.partition("=")
        flag = flag.lstrip("-") if arg.startswith("-") else ""
        if flag in ("c", "config", "confdir", "format"):
            if not equal:
                value = next(iterator, "")
            if flag != "format" and ("://" in value or value in ("stdin:", "-")):
                raise ValueError("nonlocal configuration")
            result.extend(["-" + flag, value])
    return result


def public_fields(document, source):
    results = []
    if not isinstance(document, dict):
        return results
    inbounds = document.get("inbounds", [])
    if not isinstance(inbounds, list):
        return results
    for index, inbound in enumerate(inbounds):
        if not isinstance(inbound, dict):
            continue
        stream = inbound.get("streamSettings")
        if not isinstance(stream, dict):
            continue
        settings = stream.get("realitySettings")
        if not isinstance(settings, dict):
            continue
        # Construct a new object: never print the input dictionary or parser errors.
        row = {"来源": source, "入站序号": index + 1}
        for key in ("target", "dest"):
            value = settings.get(key)
            if isinstance(value, (str, int)) and not isinstance(value, bool):
                row[key] = value
        names = settings.get("serverNames")
        row["serverNames"] = [x for x in names if isinstance(x, str)] if isinstance(names, list) else []
        if "target" in row or "dest" in row or row["serverNames"]:
            results.append(row)
    return results


def dump_config(executable, flags, cwd, environment):
    try:
        result = subprocess.run(
            [str(executable), "run", "-dump", *flags], cwd=cwd, env=environment,
            stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
            timeout=12, check=False,
        )
        if result.returncode != 0:
            return None
        return json.loads(result.stdout)
    except (OSError, subprocess.TimeoutExpired, ValueError):
        return None


def running_configs(proc=Path("/proc")):
    jobs = []
    for entry in sorted(proc.iterdir()):
        if not entry.name.isdigit():
            continue
        try:
            exe_path = os.readlink(entry / "exe").removesuffix(" (deleted)")
            if not Path(exe_path).name.lower().startswith("xray"):
                continue
            argv = (entry / "cmdline").read_bytes().decode(errors="replace").rstrip("\0").split("\0")
            if "-dump" in argv or "-test" in argv:
                continue
            flags = config_flags(argv)
            env = os.environ.copy()
            for key in LOCATION_KEYS:
                env.pop(key, None)
            # Only preserve config-location environment variables, never display them.
            for item in (entry / "environ").read_bytes().split(b"\0"):
                key, separator, value = item.partition(b"=")
                name = os.fsdecode(key)
                if separator and name in LOCATION_KEYS:
                    env[name] = os.fsdecode(value)
            jobs.append((entry / "exe", flags, entry / "cwd", env, "运行中 Xray PID " + entry.name))
        except (OSError, ValueError):
            continue
    return jobs


def collect(explicit_files=()):
    results, failed = [], 0
    jobs = [] if explicit_files else running_configs()
    for exe, flags, cwd, env, source in jobs:
        document = dump_config(exe, flags, cwd, env)
        if document is None:
            failed += 1
        else:
            results.extend(public_fields(document, source))
    if jobs:
        return results, failed, "按运行中进程参数读取当前磁盘配置；不代表已核对进程内存中的配置。"

    executable = next((x for x in (shutil.which("xray"), "/usr/local/bin/xray", "/usr/bin/xray")
                       if x and os.path.isfile(x) and os.access(x, os.X_OK)), None)
    candidates = [Path(x) for x in explicit_files]
    if not candidates:
        for directory in ("/usr/local/etc/xray", "/etc/xray"):
            parent = Path(directory)
            if parent.is_dir():
                candidates.extend(sorted(p for p in parent.iterdir()
                                         if p.suffix in (".json", ".jsonc", ".yaml", ".yml", ".toml")))
    env = os.environ.copy()
    for key in LOCATION_KEYS:
        env.pop(key, None)
    for number, path in enumerate(candidates, 1):
        if not path.is_file():
            failed += 1
            continue
        source = ("指定配置文件 " if explicit_files else "候选配置文件 ") + str(number)
        if executable:
            document = dump_config(executable, ["-config", str(path.resolve())], "/", env)
        else:
            try:
                document = json.loads(path.read_text(encoding="utf-8-sig"))
            except (OSError, ValueError):
                document = None
        if document is None:
            failed += 1
        else:
            results.extend(public_fields(document, source))
    return results, failed, "读取指定或常见路径下的配置文件，未确认它们正在使用。"


def main():
    results, failed, note = collect(sys.argv[1:])
    print(json.dumps({"说明": note, "REALITY": results, "未能解析的配置数": failed},
                     ensure_ascii=False, indent=2))
    if not results:
        print("未识别到 REALITY 目标。可在 --xray-info 后附上实际配置文件的路径；无需粘贴完整配置。")


if __name__ == "__main__":
    main()
PY_XRAY_FIELDS
}

usage() {
    cat <<'INFO'
REX2 · Rust REALITY/VLESS 服务端实验版 0.3.0 — Debian 12/13 x86_64
用法：
  bash rex2.sh                         打开交互安装/管理菜单
  bash rex2.sh --install               自定义参数、本机编译、安装并按选择启动
  bash rex2.sh --configure             修改端口、目标站、SNI、凭据和高级参数
  bash rex2.sh --client                显示 VLESS 链接并导出 Mihomo 配置片段
  bash rex2.sh --status                查看服务状态
  bash rex2.sh --start                 启动/重启，并设置开机自启
  bash rex2.sh --stop                  停止 Rust 服务
  bash rex2.sh --logs                  查看服务日志
  bash rex2.sh --network               BBR/FQ、3F2参数与恢复
  bash rex2.sh --micro-menu            28项控制中心
  bash rex2.sh --micro-28              应用Rust版第28项默认组
  bash rex2.sh --cleanup-menu          设置每日磁盘清理
  bash rex2.sh --cleanup-preview       预览清理范围
  bash rex2.sh --cleanup               立即清理
  bash rex2.sh --host-status           查看主机实际运行值
  bash rex2.sh --host-recover          恢复未完成的主机/网卡事务
  bash rex2.sh --xray-info [配置路径]    只查看 target/dest、serverNames
  bash rex2.sh --verify                只校验内嵌源码包
  bash rex2.sh --help                  查看说明

可以自定义监听端口（含 443）、目标站、SNI、UUID、shortId、私钥和高级参数。
回车保留现有凭据；新装自动生成。新 VPS 无需预装 Xray；读取已有目标站是可选项。
确认后写入配置；默认立即启动并设置开机自启，也可以选择暂不启动。
成功安装后输入 rrv 打开菜单。程序/配置应用失败时尝试恢复此前版本。
首次编译、下载工具链和依赖需要联网。更新内核需重新下载新版安装脚本执行。
默认3F2（26项、BBR/FQ）、Rust版第28项可用默认组、每日自动清理。
安装时可选keep保留系统网络值、关闭自动清理，并自定义服务参数。
3F2修改系统级TCP参数；内核缺少BBR或队列无法恢复时会明确报错。
28项按Rust能力适配：Go专属项不适用；Dnsmasq接管、原127项网络包未移植。
这是Rust实验服务；Debian12/13、XanMod和用户VPS实机仍未验证。
INFO
}

mode=${1:-menu}
case "$mode" in
    --help|-h) usage; exit 0 ;;
    --xray-info) shift; show_xray_info "$@"; exit 0 ;;
    --verify|menu|install|--install|--configure|--client|--status|--start|--stop|--logs|--micro-menu|--micro-28|--network|--cleanup-menu|--cleanup|--cleanup-preview|--host-status|--host-recover)
        [[ $# -le 1 ]] || { usage >&2; exit 2; }
        [[ $mode == --verify ]] || mode=${mode#--}
        ;;
    *) usage >&2; exit 2 ;;
esac

if [[ $mode != --verify ]]; then
    [[ ${EUID} -eq 0 ]] || { echo '请使用 root 执行安装。' >&2; exit 1; }
    [[ $(uname -s) == Linux && $(uname -m) == x86_64 ]] || { echo '需要 Linux x86_64。' >&2; exit 1; }
    # shellcheck source=/dev/null
    source /etc/os-release
    [[ ${ID:-} == debian && ( ${VERSION_ID:-} == 12 || ${VERSION_ID:-} == 13 ) ]] || { echo '此安装入口适用于 Debian 12 或 13。' >&2; exit 1; }
    command -v systemctl >/dev/null || { echo '需要 systemd/systemctl。' >&2; exit 1; }
fi

payload_tmp=$(mktemp -d)
trap 'rm -rf -- "$payload_tmp"' EXIT
payload_line=$(awk '/^__REALITY_SOURCE_PAYLOAD__$/ {print NR + 1; exit}' "${BASH_SOURCE[0]}")
[[ $payload_line =~ ^[0-9]+$ ]] || { echo '内嵌源码包缺失，请重新上传完整脚本。' >&2; exit 1; }
tail -n +"$payload_line" "${BASH_SOURCE[0]}" | base64 --decode > "$payload_tmp/source.zip"
if ! printf '%s  %s\n' '5974cf714c934b4bceae9173efaeddfe4b617390a2e0d422684e9d8b7cd7ae67' "$payload_tmp/source.zip" | sha256sum --check --status; then
    echo '内嵌源码包校验失败，请重新下载并上传完整脚本。' >&2
    exit 1
fi
echo '内嵌源码包校验通过。'
[[ $mode == --verify ]] && exit 0

if ! command -v unzip >/dev/null || ! command -v python3 >/dev/null || ! command -v openssl >/dev/null || ! command -v curl >/dev/null || ! command -v tc >/dev/null || ! command -v ethtool >/dev/null || ! command -v modprobe >/dev/null || [[ ! -r /etc/ssl/certs/ca-certificates.crt ]]; then
    apt-get update
    apt-get install -y --no-install-recommends unzip python3 openssl curl ca-certificates iproute2 ethtool kmod util-linux
fi

work_base=${REALITY_LAB_WORKDIR:-/root/reality-rust-builds}
[[ $work_base == /* ]] || { echo 'REALITY_LAB_WORKDIR 必须为绝对路径。' >&2; exit 1; }
build_dir="$work_base/0.3.0-5974cf714c93"
mkdir -p -- "$build_dir"
unzip -q -o "$payload_tmp/source.zip" -d "$build_dir"
python3 "$build_dir/reality-vision-lab/scripts/manage.py" \
    --project "$build_dir/reality-vision-lab" --installer-self "$(realpath -- "${BASH_SOURCE[0]}")" --action "$mode"
exit 0
